import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;

// Runnable harness: supplies the playlist that the printed snippet assumes
// has already been built earlier in PlaylistApp.
public class EnergyPlaylistDemo {

    static class Song {
        private final String title;
        private final String artist;
        private final int energyLevel;

        Song(String title, String artist, int energyLevel) {
            this.title = title;
            this.artist = artist;
            this.energyLevel = energyLevel;
        }

        public int getEnergyLevel() {
            return energyLevel;
        }

        @Override
        public String toString() {
            return title + " by " + artist + " (energy " + energyLevel + ")";
        }
    }

    public static void main(String[] args) {
        List<Song> playlist = new ArrayList<>();
        playlist.add(new Song("Bohemian Rhapsody", "Queen", 7));
        playlist.add(new Song("Blinding Lights", "The Weeknd", 9));
        playlist.add(new Song("Someone Like You", "Adele", 3));
        playlist.add(new Song("Uptown Funk", "Bruno Mars", 10));
        playlist.add(new Song("Fix You", "Coldplay", 4));

        System.out.println("\n--- Priority Playlist (Songs by Energy, High \u2192 Low) ---");
        PriorityQueue<Song> energyQueue = new PriorityQueue<>(
                Comparator.comparingInt(Song::getEnergyLevel).reversed());
        energyQueue.addAll(playlist);

        System.out.println("Processing by energy with poll():");
        while (!energyQueue.isEmpty()) {
            Song nextSong = energyQueue.poll();
            System.out.println("Playing: " + nextSong);
        }
    }
}
